"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["72380"],{50951(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>i,contentTitle:()=>l,toc:()=>h,assets:()=>r});var n=JSON.parse('{"id":"tianya/mathmmarena","title":"","description":"Do all girls who love math act so unexpectedly? Even as the idol\'s die-hard fan, I was deeply surprised when my idol suddenly challenged all men in the world yesterday. After a day of careful thought, I finally perceived some subtleties in my idol\'s eight gates. Let me share them for everyone\'s amusement, and I also hope my idol won\'t look down on all men.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/mathmmarena.md","sourceDirName":"tianya","slug":"/tianya/mathmmarena","permalink":"/en/tianya/mathmmarena","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"mathmmarena","title":"","hide_table_of_contents":true,"sidebar_label":"Professional analysis of the eight rounds of the \\"Math Girl\\" idol challenge (non-professionals stay out). Note: (post by Chan\'s alias)"},"sidebar":"tianyaSidebar","previous":{"title":"First couplet: \\"Japan rises in the east, shining over Shikoku and Kyushu\\" \u2014 this lady continues to challenge all men in the world!","permalink":"/en/tianya/continuetochallengemen"},"next":{"title":"Girl, let me tell you, there\'s a kind of stick that gets thicker the more you rub it!!!!! (Note: Chan\'s alias\'s deleted post)","permalink":"/en/tianya/somestick"}}'),o=a(74848),s=a(28453);let i={id:"mathmmarena",title:"",hide_table_of_contents:!0,sidebar_label:'Professional analysis of the eight rounds of the "Math Girl" idol challenge (non-professionals stay out). Note: (post by Chan\'s alias)'},l="A Professional Analysis of the Math Girl Idol's Eight-Gate Arena (Non-professionals Keep Out) Note: (Post by Chan's alternate account)",r={},h=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"a-professional-analysis-of-the-math-girl-idols-eight-gate-arena-non-professionals-keep-out-note-post-by-chans-alternate-account",children:"A Professional Analysis of the Math Girl Idol's Eight-Gate Arena (Non-professionals Keep Out) Note: (Post by Chan's alternate account)"})}),"\n",(0,o.jsx)(t.p,{children:"Do all girls who love math act so unexpectedly? Even as the idol's die-hard fan, I was deeply surprised when my idol suddenly challenged all men in the world yesterday. After a day of careful thought, I finally perceived some subtleties in my idol's eight gates. Let me share them for everyone's amusement, and I also hope my idol won't look down on all men."}),"\n",(0,o.jsx)(t.p,{children:'Gate One: Compose to the set rhyme on the given topic. Someone like the Sixth Patriarch who "establishes no written word" would have to step aside and leave.'}),"\n",(0,o.jsx)(t.p,{children:'Gate Two: A major question of Chan Buddhism. At this point, even those with heaven-reaching skills and mastery of textual prajna won\'t find traction. Gates One and Two form a deadlock: those who establish no written word die at Gate One; those who establish written word perish at Gate Two. Between establishing and not establishing, perhaps no more than a few can sneak through -- this is probably a remake of the famous "up the tree" koan in Chan Buddhism.'}),"\n",(0,o.jsx)(t.p,{children:"If three or five people truly penetrate Gates One and Two, the idol's Gate Three is also genuinely challenging. Music relates to natural talent. Without sufficient talent, setting a famous passage from Shakespeare to music at this point -- difficult indeed! The idol must already have full confidence in this gate. I believe this is the idol's proud forte. Those who can pass here number perhaps one or two at most."}),"\n",(0,o.jsx)(t.p,{children:"The mathematics and physics problems of Gates Four and Five are both monumental problems. Solving just one could earn posthumous fame. Even as a die-hard fan, I don't quite dare believe the idol can completely solve both problems. Most likely the idol has deep insights into these problems and therefore dares to use them as gates. Gate Four especially -- approaching from Yogacara philosophy and connecting to modern physics, this insight alone is not something ordinary people can achieve. The mysteries within -- if the idol doesn't say, I dare not speak out of turn. Those who know, know."}),"\n",(0,o.jsx)(t.p,{children:"After passing Gates Four and Five, one's energy would be more than half spent. Gate Six brings an economics problem, and it's hands-on real work -- bookworms would have no choice but to raise the white flag at this point. If truly one person can pass these six gates, the seven modes of singing in Gate Seven would probably finish them off. From the idol's scattered remarks, I can tell the idol is an expert singer, and these seven modes are probably among her specialties. Waiting at ease for the exhausted challenger -- how could any challenger not be defeated?"}),"\n",(0,o.jsx)(t.p,{children:"The setup of the final gate reveals the idol's attention to detail. Anyone who can truly pass seven gates is probably not young anymore. The idol is probably in the prime of youth and feels perfectly secure about this."}),"\n",(0,o.jsx)(t.p,{children:"I've wildly guessed at the idol's calculations, but even Guan Yunchang only passed five gates. These eight gates -- I'd better step aside. Let's see which hero can prove to be a true hero!"})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,a){a.d(t,{R:()=>i,x:()=>l});var n=a(96540);let o={},s=n.createContext(o);function i(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);